"use client"

import * as React from "react"
import { cn } from "@/lib/utils"

type RichTextEditorProps = {
  content?: string
  onChange?: (html: string) => void
  placeholder?: string
  className?: string
}

function RichTextEditorSkeleton({ placeholder, className }: Pick<RichTextEditorProps, "placeholder" | "className">) {
  return (
    <div className={cn("flex flex-col rounded-lg border border-input", className)}>
      <div className="h-[38px] border-b border-border" />
      <div className="min-h-32 p-3 text-sm text-text-tertiary">{placeholder}</div>
    </div>
  )
}

// TipTap is a regular dependency (bundlers resolve this import at build time,
// so it cannot be optional), but it is only imported inside the lazy chunk:
// apps that never render the editor never download it.
const RichTextEditorInner = React.lazy(() => import("./rich-text-editor-inner"))

function RichTextEditor(props: RichTextEditorProps) {
  const [mounted, setMounted] = React.useState(false)
  React.useEffect(() => setMounted(true), [])
  const fallback = <RichTextEditorSkeleton placeholder={props.placeholder ?? "Write something..."} className={props.className} />
  if (!mounted) return fallback
  return (
    <React.Suspense fallback={fallback}>
      <RichTextEditorInner {...props} />
    </React.Suspense>
  )
}

export { RichTextEditor, RichTextEditorSkeleton }
export type { RichTextEditorProps }

"use client"

import * as React from "react"
import { useEditor, EditorContent, type Editor } from "@tiptap/react"
import StarterKit from "@tiptap/starter-kit"
import Placeholder from "@tiptap/extension-placeholder"
import { Bold, Italic, Underline as UnderlineIcon, List, ListOrdered, Link as LinkIcon } from "lucide-react"
import { Separator } from "@/components/ui/separator"
import { cn } from "@/lib/utils"
import { RichTextEditorSkeleton, type RichTextEditorProps } from "./rich-text-editor"

function RichTextEditorToolbarButton({
  active,
  disabled,
  onClick,
  label,
  children,
}: {
  active?: boolean
  disabled?: boolean
  onClick: () => void
  /** Accessible name — the buttons only show an icon. */
  label: string
  children: React.ReactNode
}) {
  return (
    <button
      aria-label={label}
      aria-pressed={active}
      title={label}
      type="button"
      disabled={disabled}
      onClick={onClick}
      className={cn(
        "flex size-7 items-center justify-center rounded-md text-text-secondary outline-none hover:bg-muted focus-visible:ring-1 focus-visible:ring-ring disabled:pointer-events-none disabled:opacity-40 [&_svg]:size-4",
        active && "bg-muted text-foreground"
      )}
    >
      {children}
    </button>
  )
}

function RichTextEditorToolbar({ editor }: { editor: Editor }) {
  return (
    <div className="flex items-center gap-0.5 border-b border-border p-1.5">
      <RichTextEditorToolbarButton
        label="Bold"
        active={editor.isActive("bold")}
        onClick={() => editor.chain().focus().toggleBold().run()}
      >
        <Bold />
      </RichTextEditorToolbarButton>
      <RichTextEditorToolbarButton
        label="Italic"
        active={editor.isActive("italic")}
        onClick={() => editor.chain().focus().toggleItalic().run()}
      >
        <Italic />
      </RichTextEditorToolbarButton>
      <RichTextEditorToolbarButton
        label="Underline"
        active={editor.isActive("underline")}
        onClick={() => editor.chain().focus().toggleUnderline().run()}
      >
        <UnderlineIcon />
      </RichTextEditorToolbarButton>
      <Separator orientation="vertical" className="mx-1 h-5" />
      <RichTextEditorToolbarButton
        label="Bulleted list"
        active={editor.isActive("bulletList")}
        onClick={() => editor.chain().focus().toggleBulletList().run()}
      >
        <List />
      </RichTextEditorToolbarButton>
      <RichTextEditorToolbarButton
        label="Numbered list"
        active={editor.isActive("orderedList")}
        onClick={() => editor.chain().focus().toggleOrderedList().run()}
      >
        <ListOrdered />
      </RichTextEditorToolbarButton>
      <Separator orientation="vertical" className="mx-1 h-5" />
      <RichTextEditorToolbarButton
        label="Link"
        active={editor.isActive("link")}
        onClick={() => {
          const url = window.prompt("URL")
          if (url) editor.chain().focus().setLink({ href: url }).run()
          else editor.chain().focus().unsetLink().run()
        }}
      >
        <LinkIcon />
      </RichTextEditorToolbarButton>
    </div>
  )
}

// Loaded lazily by rich-text-editor.tsx so @tiptap/* stays an optional peer:
// this file is the only one that imports it, and tsup splits it into its own chunk.
function RichTextEditorInner({
  content,
  onChange,
  placeholder = "Write something...",
  className,
}: RichTextEditorProps) {
  const editor = useEditor({
    immediatelyRender: false,
    extensions: [
      StarterKit.configure({
        link: { openOnClick: false, autolink: true },
      }),
      Placeholder.configure({ placeholder }),
    ],
    content,
    onUpdate: ({ editor }) => onChange?.(editor.getHTML()),
    editorProps: {
      attributes: {
        class:
          "min-h-32 p-3 text-sm text-foreground outline-none [&_a]:text-text-link [&_a]:underline [&_ul]:list-disc [&_ul]:pl-5 [&_ol]:list-decimal [&_ol]:pl-5 [&_p.is-editor-empty:first-child::before]:text-text-tertiary [&_p.is-editor-empty:first-child::before]:content-[attr(data-placeholder)] [&_p.is-editor-empty:first-child::before]:float-left [&_p.is-editor-empty:first-child::before]:pointer-events-none [&_p.is-editor-empty:first-child::before]:h-0",
      },
    },
  })

  if (!editor) return <RichTextEditorSkeleton placeholder={placeholder} className={className} />

  return (
    <div className={cn("flex flex-col rounded-lg border border-input has-[[contenteditable]:focus]:border-ring", className)}>
      <RichTextEditorToolbar editor={editor} />
      <EditorContent editor={editor} />
    </div>
  )
}

export default RichTextEditorInner

"use client"

import { Separator as SeparatorPrimitive } from "@base-ui/react/separator"
import { cn } from "cn"

function Separator({
  className,
  orientation = "horizontal",
  dashed = false,
  ...props
}: SeparatorPrimitive.Props & { dashed?: boolean }) {
  return (
    <SeparatorPrimitive
      data-slot="separator"
      orientation={orientation}
      className={cn(
        dashed
          ? "shrink-0 border-border data-horizontal:h-0 data-horizontal:w-full data-horizontal:border-t data-vertical:h-full data-vertical:w-0 data-vertical:self-stretch data-vertical:border-l border-dashed"
          : "shrink-0 bg-border data-horizontal:h-px data-horizontal:w-full data-vertical:w-px data-vertical:self-stretch",
        className
      )}
      {...props}
    />
  )
}

export { Separator }
